package com.servicehub.api;
import com.servicehub.domain.*; import jakarta.validation.constraints.NotBlank; import java.time.Instant; import java.util.UUID;
public final class RequestDtos { private RequestDtos(){} public record Create(@NotBlank String title,String description,String category,String priority){} public record Update(RequestStatus status, UUID assigneeId){} public record View(UUID id,String reference,String title,String description,String category,String priority,RequestStatus status,String customer,String assignee,Instant createdAt,Instant updatedAt){ public static View from(ServiceRequest r){return new View(r.getId(),r.getReference(),r.getTitle(),r.getDescription(),r.getCategory(),r.getPriority(),r.getStatus(),r.getCustomer().getDisplayName(),r.getAssignee()==null?null:r.getAssignee().getDisplayName(),r.getCreatedAt(),r.getUpdatedAt());} } }
